1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface Incident {
23	  cause: string;
24	  damages: Damage[];
25	}
26	
27	export interface ClaimStep {
28	  op: "claim";
29	  policy: number;
30	  incident: Incident;
31	}
32	
33	export type Step = QuoteStep | ClaimStep;
34	
35	export interface Scenario {
36	  customer: Customer;
37	  steps: Step[];
38	}
39	
40	export interface QuoteResult {
41	  premium: number;
42	}
43	
44	export interface ClaimResult {
45	  payout: number;
46	  remainingCap: number;
47	}
48	
49	export type StepResult = QuoteResult | ClaimResult;
50	
51	export interface ScenarioOutput {
52	  results: StepResult[];
53	}
54	
55	const PROCESSING_FEE = 5;
56	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
57	
58	const BASE_PREMIUMS: Record<string, number> = {
59	  sword: 100,
60	  amulet: 60,
61	  staff: 80,
62	  potion: 40,
63	  rune: 25,
64	  moonstone: 25,
65	};
66	
67	/**
68	 * What each item is insured FOR — distinct from its base premium above.
69	 * A block of 3 alike components discounts the premium only, never this sum.
70	 */
71	const INSURANCE_VALUES: Record<string, number> = {
72	  sword: 1000,
73	  amulet: 600,
74	  staff: 800,
75	  potion: 400,
76	  rune: 250,
77	  moonstone: 250,
78	};
79	
80	const DEDUCTIBLE_PER_DAMAGE = 100;
81	const CAP_MULTIPLIER = 2;
82	
83	/** Premiums round up — the MHPCO's favour. */
84	const roundPremium = (amount: number): number => Math.ceil(amount);
85	
86	/** Payouts round down — the MHPCO's favour too, hence the opposite direction. */
87	const roundPayout = (amount: number): number => Math.floor(amount);
88	
89	const policyCap = (items: Item[]): number =>
90	  items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0) *
91	  CAP_MULTIPLIER;
92	
93	/** Damage to a very highly enchanted item is only half reimbursed. */
94	const REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
95	const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
96	
97	/**
98	 * The share of a damage amount the MHPCO reimburses, before the deductible.
99	 *
100	 * PLACEHOLDER in the `undefined` case, not intended behaviour: a damage naming
101	 * an item type the policy does not cover currently resolves to no item and is
102	 * reimbursed in FULL. Such a claim must be REJECTED; the pending
103	 * "damaged item is not part of the policy" test owns replacing this, at which
104	 * point the `| undefined` should leave this signature.
105	 */
106	const reimbursementRate = (item: Item | undefined): number =>
107	  (item?.enchantment ?? 0) >= REIMBURSEMENT_ENCHANTMENT_THRESHOLD
108	    ? HIGH_ENCHANTMENT_REIMBURSEMENT_RATE
109	    : 1;
110	
111	const claimPayout = (
112	  incident: Incident,
113	  insuredItems: Item[],
114	  remainingCap: number,
115	): number => {
116	  // Reimburse first, deduct second: a 1000 G damage at 50 % is 500 − 100 = 400,
117	  // not (1000 − 100) / 2 = 450.
118	  const reimbursed = incident.damages.reduce((sum, damage) => {
119	    const item = insuredItems.find((candidate) => candidate.type === damage.itemType);
120	    return (
121	      sum + damage.amount * reimbursementRate(item) - DEDUCTIBLE_PER_DAMAGE
122	    );
123	  }, 0);
124	  // Rounded HERE, after the cap clamp, so the one integer value flows into both
125	  // the reported payout and the cap decrement — otherwise a fraction leaks into
126	  // the remaining cap even when the payout itself reads clean.
127	  return roundPayout(Math.min(reimbursed, remainingCap));
128	};
129	
130	const BLOCK_SIZE = 3;
131	const BLOCK_BASE_PREMIUM = 60;
132	
133	const countByType = (items: Item[]): Map<string, number> => {
134	  const counts = new Map<string, number>();
135	  for (const item of items) {
136	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
137	  }
138	  return counts;
139	};
140	
141	/** A group of exactly 3 alike components is priced as one building block. */
142	const groupBasePremium = (type: string, count: number): number =>
143	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];
144	
145	const LOYALTY_DISCOUNT_RATE = 0.2;
146	const LOYALTY_YEARS_THRESHOLD = 2;
147	const FOLLOWUP_DISCOUNT_RATE = 0.15;
148	
149	const CURSE_SURCHARGE_RATE = 0.5;
150	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
151	const SURCHARGE_ENCHANTMENT_THRESHOLD = 5;
152	
153	/**
154	 * Rates are SUMMED here and multiplied by the base premium once by the caller,
155	 * so two modifiers on one item are additive (0.5 + 0.3) rather than
156	 * compounding (× 1.5 × 1.3) — per the spec's integration example.
157	 */
158	const itemSurchargeRate = (item: Item): number => {
159	  const curseRate = item.cursed ? CURSE_SURCHARGE_RATE : 0;
160	  const highEnchantmentRate =
161	    (item.enchantment ?? 0) >= SURCHARGE_ENCHANTMENT_THRESHOLD
162	      ? HIGH_ENCHANTMENT_SURCHARGE_RATE
163	      : 0;
164	  return curseRate + highEnchantmentRate;
165	};
166	
167	/**
168	 * Item-specific surcharges apply to the affected item's OWN base premium, so
169	 * they need a per-item pass — the grouping in `countByType` collapses both
170	 * `cursed` and `enchantment`.
171	 */
172	const itemSurcharges = (items: Item[]): number =>
173	  items.reduce(
174	    (sum, item) => sum + BASE_PREMIUMS[item.type] * itemSurchargeRate(item),
175	    0,
176	  );
177	
178	/** Is this contract a follow-up, i.e. not the customer's first in the run? */
179	const isFollowUpContract = (stepIndex: number): boolean => stepIndex > 0;
180	
181	const quotePremium = (
182	  step: QuoteStep,
183	  customer: Customer,
184	  stepIndex: number,
185	): number => {
186	  // Policy-scoped modifiers below are percentages of THIS total, never of a
187	  // running total — hence the explicit `policy` in the name: item surcharges
188	  // are percentages of each item's OWN base premium instead.
189	  const policyBasePremium = [...countByType(step.items)].reduce(
190	    (sum, [type, count]) => sum + groupBasePremium(type, count),
191	    0,
192	  );
193	
194	  /**
195	   * A conditional policy-scoped modifier: a rate on the policy base premium,
196	   * applied only when it is due. The two users differ solely in rate and
197	   * predicate — and deliberately in their INPUT: loyalty reads the customer,
198	   * the follow-up discount reads the step's position. That difference in input
199	   * is why the terms stay separate in the sum below rather than collapsing
200	   * into one lumped "adjustments" subtotal.
201	   */
202	  const policyModifier = (rate: number, isDue: boolean): number =>
203	    isDue ? policyBasePremium * rate : 0;
204	
205	  // Unconditional — every item in a quote counts as a first insurance — so it
206	  // does not go through `policyModifier`, which exists to gate a rate.
207	  const firstInsuranceSurcharge =
208	    policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;
209	  const loyaltyDiscount = policyModifier(
210	    LOYALTY_DISCOUNT_RATE,
211	    customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD,
212	  );
213	  const followUpDiscount = policyModifier(
214	    FOLLOWUP_DISCOUNT_RATE,
215	    isFollowUpContract(stepIndex),
216	  );
217	
218	  return (
219	    policyBasePremium +
220	    itemSurcharges(step.items) +
221	    firstInsuranceSurcharge -
222	    loyaltyDiscount -
223	    followUpDiscount +
224	    PROCESSING_FEE
225	  );
226	};
227	
228	/** A policy as it stands: what it covers, and how much cap it has left. */
229	interface PolicyState {
230	  items: Item[];
231	  remainingCap: number;
232	}
233	
234	/**
235	 * Settles one claim against its policy's remaining cap, DECREMENTING that cap
236	 * in `policiesByStepIndex` — successive claims on one policy must each see the
237	 * previous one's decrement, so this is deliberately not a pure function.
238	 */
239	const claimResult = (
240	  step: ClaimStep,
241	  policiesByStepIndex: Map<number, PolicyState>,
242	): ClaimResult => {
243	  // PLACEHOLDER, not intended behaviour: a claim naming a policy that no quote
244	  // step created currently reads as an empty policy with zero cap, so it pays
245	  // out 0. Such a claim must be REJECTED; the pending dangling-policy test owns
246	  // replacing this.
247	  const policy = policiesByStepIndex.get(step.policy) ?? {
248	    items: [],
249	    remainingCap: 0,
250	  };
251	  const payout = claimPayout(step.incident, policy.items, policy.remainingCap);
252	  const remainingCap = policy.remainingCap - payout;
253	  policiesByStepIndex.set(step.policy, { ...policy, remainingCap });
254	  return { payout, remainingCap };
255	};
256	
257	export const runScenario = (scenario: Scenario): ScenarioOutput => {
258	  // Claim steps reference a policy by the index of the quote step that created
259	  // it, and the remaining cap persists across claims — so the steps cannot be
260	  // processed independently of one another. That cross-step state is why this
261	  // stays an explicit loop: a fold would have to carry both the result list and
262	  // this ledger in one accumulator, hiding the sequencing rather than showing it.
263	  const policiesByStepIndex = new Map<number, PolicyState>();
264	  const results: StepResult[] = [];
265	
266	  scenario.steps.forEach((step, stepIndex) => {
267	    if (step.op === "quote") {
268	      policiesByStepIndex.set(stepIndex, {
269	        items: step.items,
270	        remainingCap: policyCap(step.items),
271	      });
272	      results.push({
273	        premium: roundPremium(quotePremium(step, scenario.customer, stepIndex)),
274	      });
275	    } else {
276	      results.push(claimResult(step, policiesByStepIndex));
277	    }
278	  });
279	
280	  return { results };
281	};
282

1	import { describe, it, expect } from "vitest";
2	import { runScenario } from "./claim-office.js";
3	
4	describe("MHPCO Claim Office", () => {
5	  // --- Simplest case ---
6	  it("should charge only the processing fee for an empty item list — premium 5 G", () => {
7	    const output = runScenario({
8	      customer: { yearsWithMHPCO: 0 },
9	      steps: [{ op: "quote", items: [] }],
10	    });
11	
12	    expect(output).toEqual({ results: [{ premium: 5 }] });
13	  });
14	
15	  // --- Item base premiums (each + 5 G fee + 10 G first insurance) ---
16	  // Base premium 100 G; end-to-end for a 0-year customer this is
17	  // 100 base + 10 first-insurance surcharge + 5 processing fee = 115 G.
18	  it("should quote a plain sword — base premium 100 G", () => {
19	    const output = runScenario({
20	      customer: { yearsWithMHPCO: 0 },
21	      steps: [
22	        { op: "quote", items: [{ type: "sword", material: "steel", enchantment: 3, cursed: false }] },
23	      ],
24	    });
25	
26	    expect(output).toEqual({ results: [{ premium: 115 }] });
27	  });
28	  // Base premium 60 G; end-to-end for a 0-year customer this is
29	  // 60 base + 6 first-insurance surcharge + 5 processing fee = 71 G.
30	  it("should quote a plain amulet — base premium 60 G", () => {
31	    const output = runScenario({
32	      customer: { yearsWithMHPCO: 0 },
33	      steps: [
34	        { op: "quote", items: [{ type: "amulet", material: "silver", enchantment: 2, cursed: false }] },
35	      ],
36	    });
37	
38	    expect(output).toEqual({ results: [{ premium: 71 }] });
39	  });
40	  // Base premium 80 G; end-to-end for a 0-year customer this is
41	  // 80 base + 8 first-insurance surcharge + 5 processing fee = 93 G.
42	  it("should quote a plain staff — base premium 80 G", () => {
43	    const output = runScenario({
44	      customer: { yearsWithMHPCO: 0 },
45	      steps: [
46	        { op: "quote", items: [{ type: "staff", material: "oak", enchantment: 1, cursed: false }] },
47	      ],
48	    });
49	
50	    expect(output).toEqual({ results: [{ premium: 93 }] });
51	  });
52	  // Base premium 40 G; end-to-end for a 0-year customer this is
53	  // 40 base + 4 first-insurance surcharge + 5 processing fee = 49 G.
54	  it("should quote a plain potion — base premium 40 G", () => {
55	    const output = runScenario({
56	      customer: { yearsWithMHPCO: 0 },
57	      steps: [
58	        { op: "quote", items: [{ type: "potion", material: "glass", enchantment: 0, cursed: false }] },
59	      ],
60	    });
61	
62	    expect(output).toEqual({ results: [{ premium: 49 }] });
63	  });
64	  // Components are insured at 250 G with a 25 G base premium each.
65	  // End-to-end for a 0-year customer: 25 base + 2.5 first-insurance
66	  // surcharge + 5 fee = 32.5, rounded UP in the MHPCO's favour = 33 G.
67	  it("should quote a single rune component — base premium 25 G", () => {
68	    const output = runScenario({
69	      customer: { yearsWithMHPCO: 0 },
70	      steps: [{ op: "quote", items: [{ type: "rune" }] }],
71	    });
72	
73	    expect(output).toEqual({ results: [{ premium: 33 }] });
74	  });
75	  // Moonstone is the second component type, also 25 G base premium.
76	  // End-to-end: 25 + 2.5 + 5 = 32.5, rounded UP = 33 G (as for a rune).
77	  it("should quote a single moonstone component — base premium 25 G", () => {
78	    const output = runScenario({
79	      customer: { yearsWithMHPCO: 0 },
80	      steps: [{ op: "quote", items: [{ type: "moonstone" }] }],
81	    });
82	
83	    expect(output).toEqual({ results: [{ premium: 33 }] });
84	  });
85	
86	  // --- Building block of 3 alike components ---
87	  // 2 × 25 = 50 G base; a block needs EXACTLY 3 alike components, so no
88	  // discount applies. End-to-end: 50 + 5 + 5 = 60 G.
89	  it("should quote 2 runes — base premium 50 G (no block)", () => {
90	    const output = runScenario({
91	      customer: { yearsWithMHPCO: 0 },
92	      steps: [{ op: "quote", items: [{ type: "rune" }, { type: "rune" }] }],
93	    });
94	
95	    expect(output).toEqual({ results: [{ premium: 60 }] });
96	  });
97	  // A building block of EXACTLY 3 alike components costs 60 G base
98	  // instead of 3 × 25 = 75 G. End-to-end: 60 + 6 + 5 = 71 G.
99	  it("should quote 3 runes — base premium 60 G (block applies)", () => {
100	    const output = runScenario({
101	      customer: { yearsWithMHPCO: 0 },
102	      steps: [
103	        { op: "quote", items: [{ type: "rune" }, { type: "rune" }, { type: "rune" }] },
104	      ],
105	    });
106	
107	    expect(output).toEqual({ results: [{ premium: 71 }] });
108	  });
109	  // 4 × 25 = 100 G base — NOT block+1 (which would be 60 + 25 = 85).
110	  // A block requires exactly 3. End-to-end: 100 + 10 + 5 = 115 G.
111	  it("should quote 4 runes — base premium 100 G (no block — block requires exactly 3)", () => {
112	    const output = runScenario({
113	      customer: { yearsWithMHPCO: 0 },
114	      steps: [
115	        {
116	          op: "quote",
117	          items: [{ type: "rune" }, { type: "rune" }, { type: "rune" }, { type: "rune" }],
118	        },
119	      ],
120	    });
121	
122	    expect(output).toEqual({ results: [{ premium: 115 }] });
123	  });
124	  // Spec: 7 runes → 175 G base = 60 (one block of 3) + 4 × 25 (singles).
125	  // NOTE: 7 × 25 also equals 175, so this example does NOT discriminate
126	  // between "one block plus singles" and "no block at all" — weak cover.
127	  // It does rule out greedy blocking: floor(7/3)=2 blocks → 2×60 + 25 = 145.
128	  // End-to-end: 175 + 17.5 + 5 = 197.5, rounded UP = 198 G.
129	  it("should quote 7 runes — base premium 175 G", () => {
130	    const output = runScenario({
131	      customer: { yearsWithMHPCO: 0 },
132	      steps: [
133	        { op: "quote", items: Array.from({ length: 7 }, () => ({ type: "rune" })) },
134	      ],
135	    });
136	
137	    expect(output).toEqual({ results: [{ premium: 198 }] });
138	  });
139	
140	  // --- "Alike" components: same type, not same family ---
141	  // Resolves the spec's ❓ on "alike": same TYPE, not same family.
142	  // 3 components total, but {rune: 2, moonstone: 1} — no group of 3, so
143	  // no block: 2×25 + 1×25 = 75 G base. End-to-end: 75 + 7.5 + 5 = 87.5 → 88 G.
144	  // A "same family" reading would block all 3 → 60 G base (71 G), so this
145	  // test actively rules that interpretation out.
146	  it("should quote 2 runes + 1 moonstone — base premium 75 G (no block: different types)", () => {
147	    const output = runScenario({
148	      customer: { yearsWithMHPCO: 0 },
149	      steps: [
150	        {
151	          op: "quote",
152	          items: [{ type: "rune" }, { type: "rune" }, { type: "moonstone" }],
153	        },
154	      ],
155	    });
156	
157	    expect(output).toEqual({ results: [{ premium: 88 }] });
158	  });
159	  // Two separate blocks, one per type: 60 + 60 = 120 G base.
160	  // No flat per-item sum reaches this (6 × 25 = 150), so both the per-type
161	  // grouping and the per-group block price are load-bearing here.
162	  // End-to-end: 120 + 12 + 5 = 137 G.
163	  it("should quote 3 runes + 3 moonstones — base premium 120 G (two separate blocks)", () => {
164	    const output = runScenario({
165	      customer: { yearsWithMHPCO: 0 },
166	      steps: [
167	        {
168	          op: "quote",
169	          items: [
170	            { type: "rune" },
171	            { type: "rune" },
172	            { type: "rune" },
173	            { type: "moonstone" },
